import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.LabTable{ActionType: packet.LabTableActionReact, Position: protocol.BlockPos{1, -2, 300}, ReactionType: 12}
START_REACTION = bytes.fromhex("010203d8040c")

# generated by gophertunnel b8bd735:
# &packet.LabTable{ActionType: packet.LabTableActionReset, Position: protocol.BlockPos{0, 0, 0}, ReactionType: 0}
RESET = bytes.fromhex("0200000000")

GOLDENS = [
    pytest.param(
        v2225.LabTablePacket(
            type=v2225.LabTablePacket.Type.START_REACTION,
            pos=v2225.BlockPos(x=1, y=-2, z=300),
            reaction=v2225.LabTableReactionType.MISC_LARGE_SMOKE,
        ),
        START_REACTION,
        id="start-reaction",
    ),
    pytest.param(
        v2225.LabTablePacket(
            type=v2225.LabTablePacket.Type.RESET,
            pos=v2225.BlockPos(x=0, y=0, z=0),
            reaction=v2225.LabTableReactionType.NONE,
        ),
        RESET,
        id="reset",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_lab_table_is_packet_109(version):
    assert version.PACKETS[109] is version.LabTablePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lab_table_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lab_table_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
